    {

           using var activity =  StartCallActivity("GetCountryCodeAsync", typeof(GetCountryCode).FullName ?? "GetCountryCodeAsync");

           try
           {
             return client.GetCountryCodeAsync();
           }
           catch (Exception ex)
           {
               MarkAsError(activity, ex);
               throw;
           }
    }
